from .models import Incident, Resolution, Attempt

SCENARIOS = [
 {'id':'pool','name':'Connection pool exhaustion','label':'Recurring incident','incident':{'title':'Payments latency after replica scale-out','service':'payments-api','environment':'production','severity':'SEV1','symptoms':'Checkout requests time out. Database connection pool is exhausted after scaling from 4 to 12 replicas.','logs':'ERROR QueuePool limit of size 20 overflow 10 reached\nFATAL: too many clients already\ncheckout p99=8420ms active_connections=198/200','context':'Synthetic scenario. A recent deployment increased replica count.'}},
 {'id':'gateway','name':'Gateway 502 after deployment','label':'Configuration regression','incident':{'title':'Gateway returns 502 for catalog requests','service':'catalog-api','environment':'production','severity':'SEV2','symptoms':'Gateway 502 errors started after deployment. Upstream connection refused on port 8080.','logs':'upstream connect() failed (111: Connection refused)\nGET /catalog 502 upstream=10.0.1.24:8080','context':'Synthetic scenario. Container health is green.'}},
 {'id':'redis','name':'Redis memory pressure','label':'Capacity incident','incident':{'title':'Session writes fail during traffic peak','service':'session-service','environment':'production','severity':'SEV2','symptoms':'Redis memory is at maxmemory. OOM errors prevent session writes and users are signed out.','logs':'OOM command not allowed when used memory > maxmemory\nused_memory=2147483648 evicted_keys=0','context':'Synthetic scenario. A bulk import added long-lived cache keys.'}},
 {'id':'learning','name':'A new lesson to remember','label':'Learning loop','incident':{'title':'Inventory requests time out after deployment','service':'inventory-api','environment':'production','severity':'SEV2','symptoms':'Inventory requests time out after deployment. Dependency client retry storm increases latency.','logs':'deadline exceeded dependency=warehouse\nretry_attempts=5 timeout_ms=1000','context':'Synthetic scenario with no pre-seeded resolution. Record your finding, then investigate again.'}},
]

def seed_resolutions():
    findings=[
      ('DEMO-001',0,'Replica scale-out multiplied per-process connection limits beyond database capacity.','Restart application pods','Connection errors returned within two minutes because pool sizing was unchanged.','Correct the total connection budget','Reduced per-replica pool size in a controlled test; total connections stayed below database capacity.','Budget database connections across replicas, workers, and background jobs.'),
      ('DEMO-002',1,'Gateway upstream port remained 8080 while the new container listened on 8000.','Increase gateway timeout','Connection refused persisted because no process listened on the configured upstream port.','Correct upstream port mapping','Staging validation reached the healthy container on port 8000.','Validate upstream port mappings and readiness through the actual gateway route.'),
      ('DEMO-003',2,'Redis noeviction policy and unbounded import keys exhausted available cache memory.','Restart Redis','The data set returned at startup and memory pressure remained.','Bound import key TTLs and validate eviction policy','A staging test of bounded TTLs and an approved eviction policy restored writes.','Measure key growth and verify eviction behavior before increasing capacity.'),
    ]
    return [Resolution(incident_id=id,incident=Incident.model_validate(SCENARIOS[n]['incident']),root_cause=root,attempts=[Attempt(action=failed,outcome='failed',explanation=why,verified=True),Attempt(action=success,outcome='succeeded',explanation=result,verified=True)],lessons=lesson,confirmed=True,synthetic=True) for id,n,root,failed,why,success,result,lesson in findings]
